function drawMeter(cvEl, frac, col, icon) { const c = cvEl.getContext('2d'); c.clearRect(0, 0, 62, 62); c.lineWidth = 7; c.lineCap = 'round'; c.strokeStyle = 'rgba(30,22,12,.35)'; c.beginPath(); c.arc(31, 31, 24, 0, TAU); c.stroke(); c.strokeStyle = col; c.beginPath(); c.arc(31, 31, 24, -Math.PI / 2, -Math.PI / 2 + TAU * clamp(frac, 0, 1)); c.stroke(); c.fillStyle = '#171310'; c.beginPath(); c.arc(31, 31, 19, 0, TAU); c.fill(); c.save(); c.translate(31, 31); c.fillStyle = col; c.strokeStyle = col; if (icon === 'hp') { c.beginPath(); c.moveTo(0, 8); c.bezierCurveTo(-11, -1, -7, -10, 0, -4); c.bezierCurveTo(7, -10, 11, -1, 0, 8); c.fill(); } if (icon === 'hun') { c.beginPath(); c.arc(-2, -2, 7, 0, TAU); c.fill(); c.lineWidth = 4; c.beginPath(); c.moveTo(3, 3); c.lineTo(9, 9); c.stroke(); c.beginPath(); c.arc(10.5, 7.5, 2.2, 0, TAU); c.arc(7.5, 10.5, 2.2, 0, TAU); c.fill(); } if (icon === 'san') { c.beginPath(); c.arc(0, 0, 8.5, 0, TAU); c.fill(); c.strokeStyle = '#171310'; c.lineWidth = 1.6; c.beginPath(); c.moveTo(-5, -3); c.quadraticCurveTo(0, 0, -4, 4); c.moveTo(1, -6); c.quadraticCurveTo(4, 0, 1, 6); c.stroke(); } c.restore(); if (frac < .25 && Math.sin(G.t * 6) > 0) { c.strokeStyle = '#ff4a30'; c.lineWidth = 2; c.beginPath(); c.arc(31, 31, 28, 0, TAU); c.stroke(); } }
